        k = 1
        s = 0
        while s < diff:
            k += 1
            s += k
        if s == diff:
            results.append(k)
        elif (s - diff) % 2 == 0:
            results.append(k)
        else:
            results.append(k + 1)
    print('\n'.join(map(str, results)))

if __name__ == "__main__":
